import React, { useState, useEffect } from "react";
import { Link } from 'react-router-dom';
import searchIcon from '../img/search-icon.png';

function Toys() {
    const [toys, setToys] = useState([]);
    const [categories, setCategories] = useState([]);
    const [selectedCategory, setSelectedCategory] = useState('');
    const [searchTerm, setSearchTerm] = useState('');
    const [minPrice, setMinPrice] = useState(0);
    const [maxPrice, setMaxPrice] = useState(1000);
    const [minAge, setMinAge] = useState(0);
    const [maxAge, setMaxAge] = useState(18);

    useEffect(() => {
        fetchToys();
        fetchCategories();
    }, []);

    const fetchToys = async () => {
        try {
            const response = await fetch(`${process.env.REACT_APP_TOY_SERVICE_URL}/toys`);
            const data = await response.json();
            setToys(data);
        } catch (error) {
            console.error('Error fetching toys:', error);
        }
    };

    const fetchCategories = async () => {
        try {
            const response = await fetch(`${process.env.REACT_APP_TOY_SERVICE_URL}/category`);
            const data = await response.json();
            setCategories(data);
        } catch (error) {
            console.error('Error fetching categories:', error);
        }
    };

    const handleCategoryChange = (event) => {
        setSelectedCategory(event.target.value);
    };

    const handleSearchChange = (event) => {
        setSearchTerm(event.target.value);
    };

    const handleMinPriceChange = (event) => {
        setMinPrice(event.target.value);
    };

    const handleMaxPriceChange = (event) => {
        setMaxPrice(event.target.value);
    };

    const handleMinAgeChange = (event) => {
        setMinAge(event.target.value);
    };

    const handleMaxAgeChange = (event) => {
        setMaxAge(event.target.value);
    };

    const filteredToys = toys.filter(toy => {
        return (
            (!selectedCategory || toy.categoryId === selectedCategory) &&
            (!searchTerm || toy.name.toLowerCase().includes(searchTerm.toLowerCase())) &&
            (!minPrice || toy.price >= minPrice) &&
            (!maxPrice || toy.price <= maxPrice) &&
            (!minAge || toy.ageRange >= minAge) &&
            (!maxAge || toy.ageRange <= maxAge)
        );
    });

    return (
        <div className="toys-catalog">
            <div className="search-category-container">
                <div className="search">
                    <img src={searchIcon} className="searchIcon" alt=""></img>
                    <input
                        type="text"
                        placeholder="Поиск игрушек по имени"
                        value={searchTerm}
                        onChange={handleSearchChange}
                    />
                </div>
                <h1>Каталог игрушек</h1>
            </div>
            <div className="content">
                <div className="filters">
                    <div className="category">
                        <select value={selectedCategory} onChange={handleCategoryChange}>
                            <option key="" value="" >Все категории</option>
                            {categories.map(category => (
                                <option name="CategoryName" id="CategoryName" key={category.id} value={category.id}>{category.categoryName}</option>
                            ))}
                        </select>
                    </div>
                    <div className="price-filter">
                        <label>
                            Цена: от {minPrice} до {maxPrice} токенов
                        </label>
                        <input
                            type="range"
                            min="0"
                            max="1000"
                            value={minPrice}
                            onChange={handleMinPriceChange}
                        />
                        <input
                            type="range"
                            min="0"
                            max="1000"
                            value={maxPrice}
                            onChange={handleMaxPriceChange}
                        />
                    </div>
                    <div className="age-filter">
                        <label>
                            Возраст: от {minAge} до {maxAge} лет
                        </label>
                        <input
                            type="range"
                            min="0"
                            max="18"
                            value={minAge}
                            onChange={handleMinAgeChange}
                        />
                        <input
                            type="range"
                            min="0"
                            max="18"
                            value={maxAge}
                            onChange={handleMaxAgeChange}
                        />
                    </div>
                </div>
                <div className="toys-list">
                    {filteredToys.map(toy => (
                        <div key={toy.id} className="toy-item">
                            <img src={`${process.env.REACT_APP_TOY_SERVICE_URL}/Images/${toy.imageUrl}`} alt="" />
                            <h2>{toy.name}</h2>
                            <p>От {toy.ageRange} лет</p>
                            <p>{toy.price} Токенов</p>
                            <div className="button-item">
                                <Link to={`/toys/${toy.id}`} className="buybutton" id="button">добавить</Link>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}

export default Toys;
